/**
 * Session subclass that persists to a JSONL file on disk.
 * Extends base Session with file-backed persistence and debounced flushing.
 * Uses SessionEventState for all disk I/O operations.
 */
declare class CLISession extends Session {
    private flushTimer;
    private flushDebounceMs;
    private isDirty;
    private shouldSaveSession;
    private unflushedEvents;
    private _legacySourceFile?;
    private modelList;
    constructor({ sessionId, startTime, logger, options, }: {
        sessionId: string;
        startTime: Date;
        logger: RunnerLogger;
        options?: {
            flushDebounceMs?: number;
        };
    });
    /**
     * Set the model list to enable dynamic billing multiplier lookup.
     * @param models The list of models from CAPI
     */
    setModelList(models: Model[] | undefined): void;
    getModelList(): Model[] | undefined;
    /**
     * Override addEvent to track unflushed events and trigger debounced flush to disk
     * Note: We don't flush after the very first session.start event, only if there's an event after that
     */
    addEvent(eventData: Partial<Pick<SessionEvent, "id" | "timestamp" | "parentId">> & Omit<SessionEvent, "id" | "timestamp" | "parentId">): SessionEvent;
    setShouldSaveSession(shouldSaveSession: boolean): void;
    /**
     * Schedule a debounced flush to disk
     */
    private scheduleDebouncedFlush;
    /**
     * Force immediate flush to disk (append unflushed events)
     * Note: Filters out ephemeral events before writing
     * Handles migration from legacy format if needed
     */
    flush(): Promise<void>;
    /**
     * Get the file path for this session (for debugging/logging)
     */
    getFilePath(): string;
    setLegacySourceFile(filePath: string): void;
    /**
     * Load a session from a JSONL file
     */
    static load(sessionId: string, logger: RunnerLogger): Promise<CLISession>;
}

/**
 * SessionManager subclass that persists sessions to JSONL files.
 * Extends SessionManager<CLISession> so all methods return CLISession.
 * Uses SessionEventState for all file system operations.
 *
 * IMPORTANT: This manager ALWAYS reads from disk and does NOT persist sessions in memory.
 * This ensures:
 * - Single source of truth (disk)
 * - No memory bloat from accumulated sessions
 * - Correct behavior when sessions are modified externally
 * - Simplified concurrent access patterns
 */
declare class CLISessionManager extends SessionManager<CLISession> {
    private copilotVersion;
    constructor({ logger, version }: {
        logger: RunnerLogger;
        version?: string;
    });
    /**
     * Create a new file-backed session
     */
    createSession(options?: CreateSessionOptions): Promise<CLISession>;
    /**
     * Get existing session by ID
     * ALWAYS loads from disk to ensure freshness
     * Supports both JSONL and legacy JSON formats
     */
    getSession(sessionId: string): Promise<CLISession | undefined>;
    /**
     * Load a legacy JSON session and convert it to CLISession
     * This creates a session.import_legacy event to preserve the legacy data
     */
    private loadLegacySession;
    /**
     * List all sessions by reading from disk
     * Overrides base class to read sessions from both JSONL and legacy JSON formats
     */
    listSessions(): Promise<SessionMetadata[]>;
    /**
     * Get the most recently created/accessed session
     * Returns the session with the most recent start time
     * Overrides base class to check disk for sessions
     */
    getLastSession(): Promise<CLISession | undefined>;
    /**
     * Delete a session from disk
     */
    deleteSession(session: CLISession): Promise<void>;
    /**
     * Get the sessions directory path (for debugging/logging)
     */
    getSessionsDirectory(): string;
    setLogger(logger: RunnerLogger): void;
}

